import { useState } from 'react';
import { useBusinessCrm } from '../BusinessCrmContext';
import { useDebouncedValue, useResource } from '../hooks';
import { formatDate, formatMoney, monthRange } from '../constants';
import { Card, ErrorState, Field, Input, Loading, PageHeader, SearchBox, Select, Status, Table } from '../components/ui';
export default function Cashbook(){const crm=useBusinessCrm();const initial=monthRange();const[from,setFrom]=useState(initial.from);const[to,setTo]=useState(initial.to);const[entryType,setEntryType]=useState('');const[q,setQ]=useState('');const dq=useDebouncedValue(q);const r=useResource(()=>`/reports/cashbook?currency=${crm.currency}&from=${from}&to=${to}&entryType=${entryType}&search=${encodeURIComponent(dq)}`,[crm.currency,from,to,entryType,dq]);if(r.initialLoading)return <Loading/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;return <><PageHeader title="Cashbook" description="Actual client receipts, vendor payments, reversals and operating expenses in one cash movement ledger."/><div className="bcrm-filterbar"><Field label="From"><Input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="To"><Input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field><Field label="Movement"><Select value={entryType} onChange={e=>setEntryType(e.target.value)}><option value="">All movements</option><option value="client_receipt">Client receipts</option><option value="vendor_payment">Vendor payments</option><option value="expense">Expenses</option></Select></Field><SearchBox value={q} onChange={setQ} busy={r.loading} placeholder="Details, reference or method…"/></div><Card className="flush" title={`${r.data?.total??r.data?.rows?.length??0} cash movements`} subtitle="Running balance is calculated across the whole date range, not only the rows shown"><Table rows={r.data?.rows||[]} columns={[{key:'entry_date',label:'Date',render:x=>formatDate(x.entry_date)},{key:'entry_type',label:'Type',render:x=><Status tone={Number(x.signed_amount)>=0?'success':'warning'}>{String(x.entry_type).replaceAll('_',' ')}</Status>},{key:'notes',label:'Details'},{key:'method',label:'Method'},{key:'reference',label:'Reference'},{key:'signed_amount',label:'Movement',render:x=><strong>{formatMoney(x.signed_amount,crm.currency)}</strong>},{key:'running_balance',label:'Running balance',render:x=>formatMoney(x.running_balance,crm.currency)}]} /></Card></>}
