import { useState } from 'react';
import { Edit3, Plus, Save, Trash2 } from 'lucide-react';
import { useBusinessCrm } from '../BusinessCrmContext';
import { crmApi, messageFromError } from '../api';
import { useDebouncedValue, useResource } from '../hooks';
import { queueOperation } from '../offline/queue';
import { formatDate, formatMoney, today } from '../constants';
import { Button, Card, ErrorState, Field, Input, Loading, Modal, PageHeader, SearchBox, Select, Table, Textarea } from '../components/ui';
const blank=currency=>({expenseDate:today(),category:'Hosting',description:'',payee:'',amount:'0.00',currencyCode:currency,method:'Bank',reference:'',notes:''});
export default function Expenses(){const crm=useBusinessCrm();const[q,setQ]=useState('');const[form,setForm]=useState(null);const[error,setError]=useState('');const dq=useDebouncedValue(q);const r=useResource(()=>`/expenses?pageSize=100&currency=${crm.currency}&q=${encodeURIComponent(dq)}`,[crm.currency,dq]);const edit=x=>setForm({id:x.id,expenseDate:x.expense_date,category:x.category,description:x.description,payee:x.payee||'',amount:x.amount,currencyCode:x.currency_code,method:x.method||'',reference:x.reference||'',notes:x.notes||'',version:x.version});const save=async()=>{try{if(!navigator.onLine){if(form.id)throw new Error('Existing expenses can only be edited online.');await queueOperation('expense.create',form,crm.bootstrap?.user?.id);crm.setQueued(crm.queued+1);setForm(null);setError('Expense queued. Cashbook totals update after server synchronization.');return;}form.id?await crmApi.put(`/expenses/${form.id}`,form):await crmApi.post('/expenses',form);setForm(null);r.reload()}catch(e){setError(messageFromError(e))}};const remove=async x=>{if(!window.confirm('Void this expense? The audit trail will remain.'))return;try{await crmApi.delete(`/expenses/${x.id}`);r.reload()}catch(e){setError(messageFromError(e))}};if(r.initialLoading)return <Loading/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;const total=(r.data?.rows||[]).reduce((sum,x)=>sum+Number(x.amount),0);return <><PageHeader title="Operating expenses" description="Hosting, advertising, salaries and other costs feed directly into net profit and cashbook reports." actions={crm.has('expenses.manage')&&<Button icon={Plus} onClick={()=>setForm(blank(crm.currency))}>New expense</Button>}/>{error&&<div className="bcrm-banner warning">{error}</div>}<div className="bcrm-grid bcrm-grid-4"><Card title={`Visible ${crm.currency} expenses`}><strong>{formatMoney(total,crm.currency)}</strong></Card></div><div className="bcrm-filterbar bcrm-section"><SearchBox value={q} onChange={setQ} busy={r.loading} placeholder="Description, category or payee…"/></div><Card className="flush"><Table rows={r.data?.rows||[]} columns={[{key:'expense_date',label:'Date',render:x=>formatDate(x.expense_date)},{key:'category',label:'Category'},{key:'description',label:'Description'},{key:'payee',label:'Payee'},{key:'amount',label:'Amount',render:x=>formatMoney(x.amount,x.currency_code)},{key:'method',label:'Method'},{key:'actions',label:'',render:x=>crm.has('expenses.manage')?<div className="bcrm-actions"><Button variant="secondary" icon={Edit3} onClick={()=>edit(x)}>Edit</Button><Button variant="danger" icon={Trash2} onClick={()=>remove(x)}>Void</Button></div>:null}]} /></Card><Modal open={Boolean(form)} title={form?.id?'Edit expense':'New expense'} onClose={()=>setForm(null)} footer={<><Button variant="secondary" onClick={()=>setForm(null)}>Cancel</Button><Button icon={Save} onClick={save}>Save expense</Button></>}>{form&&<div className="bcrm-form-grid"><Field label="Date"><Input type="date" value={form.expenseDate} onChange={e=>setForm({...form,expenseDate:e.target.value})}/></Field><Field label="Category"><Select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{['Hosting','Domain','Advertising','Salary','Internet','Software','Office','Refund','Miscellaneous'].map(x=><option key={x}>{x}</option>)}</Select></Field><Field label="Description"><Input value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Payee"><Input value={form.payee} onChange={e=>setForm({...form,payee:e.target.value})}/></Field><Field label="Amount"><Input value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></Field><Field label="Currency"><Select value={form.currencyCode} onChange={e=>setForm({...form,currencyCode:e.target.value})}>{['PKR','INR','NGN'].map(x=><option key={x}>{x}</option>)}</Select></Field><Field label="Method"><Input value={form.method} onChange={e=>setForm({...form,method:e.target.value})}/></Field><Field label="Reference"><Input value={form.reference} onChange={e=>setForm({...form,reference:e.target.value})}/></Field><Field label="Notes"><Textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div>}</Modal></>}
