import { useState } from 'react';
import { useBusinessCrm } from '../BusinessCrmContext';
import { useResource } from '../hooks';
import { formatDate, formatMoney, monthRange } from '../constants';
import { Card, ErrorState, Field, Input, Loading, Metric, PageHeader, Table } from '../components/ui';
export default function Reports(){const crm=useBusinessCrm();const initial=monthRange();const[from,setFrom]=useState(initial.from);const[to,setTo]=useState(initial.to);const r=useResource(()=>`/reports/summary?currency=${crm.currency}&from=${from}&to=${to}`,[crm.currency,from,to]);if(r.loading)return <Loading/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;const d=r.data||{};const s=d.summary||{};return <><PageHeader title="Business reports" description="Revenue, collections, profit and expense analysis for a controlled date range."/><div className="bcrm-filterbar"><Field label="From"><Input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="To"><Input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div><div className="bcrm-grid bcrm-grid-4"><Metric label="Revenue" value={s.revenue} currency={crm.currency}/><Metric label="Client collections" value={s.clientCollections} currency={crm.currency} tone="cyan"/>{crm.has('vendors.view')&&<Metric label="Vendor payments" value={s.vendorPayments} currency={crm.currency} tone="amber"/>}<Metric label="Expenses" value={s.expenses} currency={crm.currency} tone="red"/>{s.grossProfit!==undefined&&<><Metric label="Gross profit" value={s.grossProfit} currency={crm.currency} tone="green"/><Metric label="Net profit" value={s.netProfit} currency={crm.currency} tone="teal"/></>}</div><div className="bcrm-grid bcrm-grid-2 bcrm-section"><Card title="Daily performance" className="flush"><Table rows={d.daily||[]} columns={[{key:'sale_date',label:'Date',render:x=>formatDate(x.sale_date)},{key:'invoices',label:'Invoices'},{key:'revenue',label:'Revenue',render:x=>formatMoney(x.revenue,crm.currency)},{key:'received',label:'Received',render:x=>formatMoney(x.received,crm.currency)},...(d.daily?.[0]?.profit!==undefined?[{key:'profit',label:'Profit',render:x=>formatMoney(x.profit,crm.currency)}]:[])]}/></Card><Card title="Top clients" className="flush"><Table rows={d.topClients||[]} columns={[{key:'name',label:'Client'},{key:'invoices',label:'Invoices'},{key:'revenue',label:'Revenue',render:x=>formatMoney(x.revenue,crm.currency)},{key:'pending',label:'Pending',render:x=>formatMoney(x.pending,crm.currency)}]}/></Card></div><div className="bcrm-grid bcrm-grid-2 bcrm-section"><Card title="Top products" className="flush"><Table rows={d.topProducts||[]} columns={[{key:'name',label:'Product'},{key:'units',label:'Units'},{key:'revenue',label:'Revenue',render:x=>formatMoney(x.revenue,crm.currency)},...(d.topProducts?.[0]?.profit!==undefined?[{key:'profit',label:'Profit',render:x=>formatMoney(x.profit,crm.currency)}]:[])]}/></Card><Card title="Expense categories" className="flush"><Table rows={d.expenseCategories||[]} columns={[{key:'category',label:'Category'},{key:'entries',label:'Entries'},{key:'amount',label:'Amount',render:x=>formatMoney(x.amount,crm.currency)}]}/></Card></div></>}
